'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = v => typeof v === 'string' ? v : JSON.stringify(v, null, 2);
const code = v => `<pre class="sr-code">${esc(fmt(present(v)))}</pre>`;
function present(value){if(Array.isArray(value))return value.map(present);if(value&&typeof value==='object'){const hidden=/^(method_id|method_revision|generator_condition|asset_condition|revision|ontology_revision|composition_revision|consumer_contract_version|compiler|format_version|source_commit|release_label|provider|system_fingerprint|.*sha256|.*_hash)$/;return Object.fromEntries(Object.entries(value).filter(([k])=>!hidden.test(k)).map(([k,v])=>[k,present(v)]));}if(typeof value==='string'&&value.startsWith('/data/workspace/'))return value.split('/').at(-1);return value;}
const details = (title,v,open=false) => `<details class="sr-json" ${open?'open':''}><summary>${esc(title)}</summary>${code(v)}</details>`;
const state = {catalog:null, db:null, case:null, tab:'ontology', timer:null, step:0, epoch:0, object:null, api:'', project:null, run:null, polling:false};
const cache = new Map();
async function json(path){if(cache.has(path))return cache.get(path);const r=await fetch(path);if(!r.ok)throw Error(`HTTP ${r.status}: ${path}`);const d=await r.json();cache.set(path,d);return d;}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,6500);}
function stop(){clearTimeout(state.timer);state.timer=null;}
function tab(name){stop();state.tab=name;document.querySelectorAll('#sr-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.sr-view,#local').forEach(v=>v.classList.toggle('active',v.id===name));}
function drawDatabases(){const q=$('#db-search').value.toLowerCase();$('#list').innerHTML=state.catalog.databases.filter(db=>db.id.toLowerCase().includes(q)).map(db=>`<div class="dbhdr ${state.db?.database===db.id?'open sel':''}" data-db="${esc(db.id)}"><span class="caret">${state.db?.database===db.id?'▼':'▶'}</span><span class="dbn">${esc(db.id)}</span><span class="cnt">${db.columns} cols</span></div>${state.db?.database===db.id?`<div class="sr-db-count">${db.sources} SQL sources · ${db.cases.length} saved ${db.cases.length===1?'query':'queries'}</div>`:''}`).join('');document.querySelectorAll('[data-db]').forEach(b=>b.onclick=()=>selectDatabase(b.dataset.db));}
async function selectDatabase(id){const epoch=++state.epoch;stop();state.pendingDb=id;state.explanationEpoch=(state.explanationEpoch||0)+1;if($('#explain'))$('#explain').innerHTML='<div class="empty">Select this database’s cached explanation.</div>';$('#detail').innerHTML='<div class="empty">Loading ontology…</div>';const db=await json(state.catalog.databases.find(d=>d.id===id).path);if(epoch!==state.epoch)return;state.db=db;state.pendingDb=null;state.case=null;state.step=0;state.object=null;drawDatabases();drawMiddle();drawOntology();drawMaintenance();drawQuery();tab('ontology');}
function drawMiddle(){const db=state.db,o=db.ontology;$('#detail').innerHTML=`<div class="lbl">Saved archive</div><h2>${esc(db.database)}</h2><div class="sr-metrics"><span><b>${o.tables.length}</b>tables</span><span><b>${o.sources.length}</b>history SQL</span><span><b>${o.objects.length}</b>objects</span></div><div class="sr-source-badge">Saved ontology · native recovered aliases</div><p class="sr-note">物理列 → 恢复名称 → 历史 SQL 来源。选择右侧列名、对象或关系查看证据。</p>`;
$('#schemawrap').innerHTML='';
$('#kbwrap').innerHTML=`<div class="sr-panel-title">Physical tables</div>${o.tables.map(t=>`<button class="sr-table-link" data-table="${esc(t.physical_table)}">${esc(t.physical_table)} <small>${t.columns.length} columns</small></button>`).join('')}<details class="sr-json sr-padding"><summary>Archive source</summary>${code(db.provenance)}</details>`;
document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{tab('ontology');$('#column-filter').value=b.dataset.table;drawColumns();});}
async function selectCase(id){const epoch=++state.epoch;stop();const info=state.db.cases.find(c=>c.id===id);const loaded=await json(info.path);if(epoch!==state.epoch)return;state.case={...loaded,result_status:info.result_status||'unknown',official_score:info.official_score??null,evaluation_reason:info.evaluation_reason||'official_score_missing'};state.step=0;document.querySelectorAll('.item.task').forEach(b=>b.classList.toggle('sel',b.dataset.case===id));drawQuery();tab('query');}
function columnRows(){const o=state.db.ontology;const objects=new Map(o.objects.filter(x=>x.kind==='column').flatMap(x=>(x.physical_identifiers||[]).map(p=>[p,x])));const recover=new Map(o.recovery.flatMap(r=>(r.prediction?.columns||[]).map(c=>[r.prediction.physical_table+'.'+c.physical_column,c])));return o.tables.flatMap(t=>t.columns.map(c=>{const p=t.physical_table+'.'+c.physical_column,obj=objects.get(p),rec=recover.get(p);const aliases=[...new Set([...(obj?.aliases||[]),...(rec?.aliases||[])])];const evidence=(obj?.evidence_ids||[]).map(e=>o.sources.find(s=>s.evidence_id===e)?.history_id||e);return {physical:p,table:t.physical_table,column:c.physical_column,aliases,evidence,obj,rec,status:obj?.family_status||obj?.interpretation_confidence||rec?.source||'physical catalogue',type:c.declared_type};}));}
function drawOntology(){const o=state.db.ontology;$('#ontology').innerHTML=`<div class="sr-heading"><h2>Ontology construction / 本体构建</h2><span class="badge">Saved archive</span></div><div class="sr-flow"><span>SQL history</span><i>→</i><span>Objects & recovered names</span><i>→</i><span>Edges / coupled families</span><i>→</i><span>Query evidence</span></div><div class="sr-card"><h3>Recovered columns / 列名恢复</h3><p class="sr-note">Aliases below are from saved native recovery and semantic-state records. Click a physical column to inspect its source SQL and object state.</p><input id="column-filter" placeholder="Filter physical column, table or recovered alias…"><div id="column-list"></div></div><div class="sr-two"><div class="sr-card"><h3>Relationship graph / 关系图</h3><div id="ontology-graph"></div></div><div class="sr-card"><h3>Selected object / 来源与状态</h3><div id="object-detail" class="empty">Select a recovered column.</div></div></div>${o.construct.length?`<div class="sr-card"><h3>Coupled family construction / 联合恢复</h3>${o.construct.map(constructHTML).join('')}</div>`:''}<div class="sr-card"><h3>Historical SQL sources / ${o.sources.length}</h3><input id="source-filter" placeholder="Filter history ID or SQL…"><div id="source-list"></div></div>`;$('#column-filter').oninput=drawColumns;$('#source-filter').oninput=drawSources;drawColumns();drawGraph();drawSources();}
function drawColumns(){const q=$('#column-filter').value.toLowerCase(),rows=columnRows().filter(r=>[r.physical,...r.aliases].join(' ').toLowerCase().includes(q));$('#column-list').innerHTML=`<table class="sr-table"><thead><tr><th>Physical identifier</th><th>Recovered aliases / name</th><th>Source history IDs</th><th>State</th></tr></thead><tbody>${rows.map(r=>`<tr data-column="${esc(r.physical)}"><td class="sr-mono">${esc(r.physical)}</td><td>${r.aliases.length?r.aliases.map(a=>`<div>${esc(a)}</div>`).join(''):'<span class="sr-muted">No saved semantic alias</span>'}</td><td class="sr-mono">${esc(r.evidence.slice(0,5).join(', '))}${r.evidence.length>5?` +${r.evidence.length-5}`:''}</td><td><span class="sr-tag">${esc(r.status)}</span></td></tr>`).join('')}</tbody></table><div class="sr-note">${rows.length} physical columns</div>`;document.querySelectorAll('[data-column]').forEach(b=>b.onclick=()=>showColumn(b.dataset.column));}
function showColumn(physical){const row=columnRows().find(r=>r.physical===physical),o=state.db.ontology;state.object=row.obj;$('#object-detail').className='';$('#object-detail').innerHTML=`<div class="sr-mono">${esc(physical)}</div><h4>${esc(row.aliases.join(' / ')||'No saved alias')}</h4>${row.obj?details('Native object state',row.obj):details('Saved recovery record',row.rec||{})}<div class="lbl">Source SQL</div>${o.sources.filter(s=>row.obj?.evidence_ids?.includes(s.evidence_id)).map(s=>`<details class="sr-json"><summary>${esc(s.history_id)}</summary>${code(s.sql)}</details>`).join('')||'<p class="sr-note">No direct column-object source retained.</p>'}`;$('#object-detail').scrollIntoView({block:'nearest',behavior:'smooth'});}
function drawSources(){const q=$('#source-filter').value.toLowerCase();$('#source-list').innerHTML=state.db.ontology.sources.filter(s=>[s.history_id,s.sql].join(' ').toLowerCase().includes(q)).map(s=>`<details class="sr-json" id="source-${esc(s.history_id.replace(/:/g,'-'))}"><summary><span class="sr-source-id">${esc(s.history_id)}</span> <span class="sr-sql-preview">${esc(s.sql.slice(0,110))}</span></summary>${code(s.sql)}<p class="sr-note">${s.facts.length} extracted facts · ${esc(s.evidence_id)}</p></details>`).join('');}
function constructHTML(c){const last=c.attempts?.at(-1)||{},first=c.attempts?.[0]||{};return `<div class="sr-construct"><div class="sr-heading"><b>${esc(c.table)}</b><span class="sr-tag">${esc(c.status)}</span></div><p class="sr-note">${esc(c.source_ids.join(', '))}</p><div class="sr-flow"><span>Propose roles</span><i>→</i><span>${first.initial_assignment_count??'?'} assignments</span><i>→</i><span>${last.feasible_assignments?.length??'?'} feasible</span><i>→</i><span>Choose / materialize</span></div>${Object.entries(c.selected_assignment||{}).map(([p,r])=>`<div class="sr-assignment"><code>${esc(p)}</code><span>→</span><b>${esc(r)}</b></div>`).join('')}${details('Proposal, observations, constraints and excluded assignments',c)}</div>`;}
function drawGraph(highlight=new Set()){const o=state.db.ontology,tables=o.tables.map(t=>t.physical_table),n=tables.length,w=680,h=Math.max(220,n*24);const points=new Map(tables.map((t,i)=>[t,{x:w/2+Math.cos(2*Math.PI*i/n-Math.PI/2)*w*.34,y:h/2+Math.sin(2*Math.PI*i/n-Math.PI/2)*h*.34}]));const edges=o.edges.map(e=>{const a=points.get(e.left.split('.')[0]),b=points.get(e.right.split('.')[0]);if(!a||!b)return '';return `<line data-edge-left="${esc(e.left)}" data-edge-right="${esc(e.right)}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#43536b" stroke-width="1.3"/>`;}).join('');const nodes=tables.map(t=>{const p=points.get(t);return `<g class="sr-graph-node"><rect x="${p.x-65}" y="${p.y-15}" width="130" height="30" rx="5" fill="#182c38" stroke="#638681"/><text x="${p.x}" y="${p.y+4}" text-anchor="middle" fill="#c6e4da" font-size="11">${esc(t)}</text></g>`;}).join('');$('#ontology-graph').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Saved ontology relationship graph">${edges}${nodes}</svg><div class="sr-note">${o.edges.length} saved edges · click an edge for physical endpoints and source IDs</div>${o.edges.map((e,i)=>details(e.left+' ↔ '+e.right,e)).join('')}`;}
function drawMaintenance(){const events=state.db.maintenance||[];$('#maintenance').innerHTML=`<div class="sr-heading"><h2>Ontology maintenance / 增量更新</h2><span class="badge">Native dependency update</span></div><p class="sr-note">Replay recorded alias revisions and source events on a copied ontology. Inspect changed names, the forward dependency closure and preserved objects.</p><select id="maintenance-event">${events.map((e,i)=>`<option value="${i}">${esc(e.title)}</option>`).join('')}</select><div id="maintenance-body"></div>`;$('#maintenance-event').onchange=()=>showMaintenance(Number($('#maintenance-event').value));showMaintenance(0);}
function showMaintenance(index){const event=state.db.maintenance?.[index];if(!event){$('#maintenance-body').innerHTML='<div class="empty">No saved maintenance event selected.</div>';return;}const r=event.receipt,objects=state.db.ontology.objects;const seed=new Set(r.delta_ids),affected=new Set(r.affected_ids),skipped=new Set(r.skipped_ids);const byId=new Map(objects.map(o=>[o.id,o]));const nodes=[...new Set([...r.delta_ids,...r.affected_ids])].slice(0,55);const pts=new Map(nodes.map((id,i)=>[id,{x:95+(i%4)*175,y:35+Math.floor(i/4)*57}]));const lines=nodes.flatMap(id=>(byId.get(id)?.depends_on||[]).filter(dep=>pts.has(dep)).map(dep=>{const a=pts.get(dep),b=pts.get(id);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#946b42" opacity=".7"/>`;})).join('');$('#maintenance-body').innerHTML=`<div class="sr-card"><div class="sr-source-badge">${esc(event.event_type)}</div><p>${esc(event.source)}</p><div class="sr-flow"><span class="delta">Δ ${r.delta_size} seeds</span><i>→</i><span class="affected">${r.affected_size} affected</span><i>→</i><span class="preserved">${r.unchanged_object_count} preserved</span></div><p class="sr-note">${esc(event.method)} · ${event.model_calls} model calls · original archive remains intact</p>${event.source_sql?details('Source event SQL',event.source_sql):''}<table class="sr-table"><thead><tr><th>Physical columns</th><th>Before / 名称</th><th>After / 名称</th><th>Change</th></tr></thead><tbody>${event.column_changes.map(c=>`<tr class="sr-updated"><td class="sr-mono">${esc(c.physical_identifiers.join(', '))}</td><td>${esc(c.before.join(' / ')||'—')}</td><td>${esc(c.after.join(' / ')||'No remaining alias')}</td><td>${esc(c.status||'updated')}</td></tr>`).join('')}</tbody></table><h3>Forward dependency closure / 依赖闭包</h3><p class="sr-note"><span class="delta">● direct delta</span> · <span class="affected">● affected dependent</span> · <span class="preserved">● preserved outside closure</span></p><svg class="sr-closure" viewBox="0 0 710 ${Math.max(110,Math.ceil(nodes.length/4)*57+20)}" role="img" aria-label="Native dependency closure">${lines}${nodes.map(id=>{const p=pts.get(id),o=byId.get(id);return `<g><rect x="${p.x-78}" y="${p.y-16}" width="156" height="34" rx="4" fill="${seed.has(id)?'#5c3832':'#493f27'}" stroke="${seed.has(id)?'#cc8b78':'#b49b61'}"/><text x="${p.x}" y="${p.y+3}" text-anchor="middle" fill="#e4d6ba" font-size="9">${esc((o?.kind||'removed')+' · '+(o?.physical_identifiers?.[0]||id).slice(0,21))}</text></g>`;}).join('')}</svg>${nodes.length<affected.size?`<p class="sr-note">Showing ${nodes.length} closure nodes. Full IDs and diff are in the receipt.</p>`:''}<details class="sr-json"><summary>Preserved column names / 未受影响列</summary><table class="sr-table"><tbody>${objects.filter(o=>o.kind==='column'&&skipped.has(o.id)).map(o=>`<tr><td>${esc(o.physical_identifiers.join(', '))}</td><td>${esc((o.aliases||[]).join(' / '))}</td><td class="preserved">preserved</td></tr>`).join('')}</tbody></table></details>${details('Native update receipt: full before/after diff',r)}</div>`;}
function drawQuery(){$('#query').innerHTML='<div class="empty">Select a saved question in the database tree, then click Run.</div>';}
function playNext(){}
async function api(path,body){if(!state.api)throw Error('Connect the local API first.');const response=await fetch(state.api+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await response.json();if(!response.ok)throw Error(d.error||`HTTP ${response.status}`);return d;}
function settings(){return {base_url:$('#model-url').value.trim(),model:$('#model-name').value.trim(),api_key_env:$('#key-env').value.trim(),compatibility:$('#model-compat').value,embedding_base_url:$('#embedding-url').value.trim(),embedding_model:$('#embedding-model').value.trim(),reranker_base_url:$('#reranker-url').value.trim(),reranker_model:$('#reranker-model').value.trim()};}
function pendingRun(active){for(const id of ['build-ontology','update-ontology','construct-family','run-queries'])$('#'+id).disabled=active||!state.project;}
async function beginRun(action){try{pendingRun(true);const d=await api('/api/runs',{project_id:state.project,action,history_text:$('#history-delta').value,retract_history_ids:$('#retract-ids').value.split(',').map(x=>x.trim()).filter(Boolean),settings:settings(),family:{table:$('#family-table').value.trim(),columns:$('#family-columns').value.split(',').map(x=>x.trim()).filter(Boolean)}});state.run=d.run_id;$('#task-events').innerHTML='';await pollRun(d.run_id,0);}catch(e){toast(e.message);pendingRun(false);}}
async function pollRun(id,offset){try{const d=await api(`/api/runs/${id}/events?after=${offset}`);for(const e of d.events){const div=document.createElement('details');div.className='sr-task-event '+(e.type==='error'?'error':'');div.innerHTML=`<summary><time>${new Date(e.time*1000).toLocaleTimeString()}</time> ${esc(e.message)}</summary>${code(e.data)}`;$('#task-events').appendChild(div);}$('#run-state').textContent=d.status;if(d.status==='running'){setTimeout(()=>pollRun(id,d.next),900);return;}const result=await api(`/api/runs/${id}/result`);pendingRun(false);if(result.error)toast(result.error);if(result.result){const payload=result.result,cases=payload.cases||[payload];const button=document.createElement('button');button.textContent='Inspect '+(payload.cases?'query results':'constructed ontology');button.onclick=()=>{const first=cases[0];state.db={database:first.database,ontology:first.ontology,provenance:first.provenance,maintenance:first.maintenance||[],cases:[]};state.case=first.prediction?first:null;drawMiddle();drawOntology();drawMaintenance();drawQuery();tab(first.prediction?'query':'ontology');if(cases.length>1){$('#schemawrap').innerHTML=cases.map((c,i)=>`<button class="sr-question" data-local-case="${i}">${esc(c.question)}</button>`).join('');document.querySelectorAll('[data-local-case]').forEach(b=>b.onclick=()=>{state.case=cases[Number(b.dataset.localCase)];state.step=0;drawQuery();tab('query');});}};$('#task-events').appendChild(button);}}catch(e){pendingRun(false);toast(e.message);}}
async function filesToBase64(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary);}
function initAPI(){$('#api-url').value=location.port==='8765'?location.origin:'http://127.0.0.1:8765';$('#connect-api').onclick=async()=>{try{state.api=$('#api-url').value.replace(/\/$/,'');const info=await api('/api/health');$('#api-status').textContent='API CONNECTED';$('#api-status').title=info.release;toast('Connected to native SR local API');}catch(e){state.api='';$('#api-status').textContent='API DISCONNECTED';toast(e.message);}};$('#import-files').onclick=async()=>{try{const db=$('#database-file').files[0],hist=$('#history-file').files[0],questions=$('#questions-file').files[0];$('#import-status').textContent='Importing…';const payload={database_id:$('#database-id').value.trim(),history_text:hist?await hist.text():'',questions_text:questions?await questions.text():'',paths:{database:$('#database-path').value.trim(),history:$('#history-path').value.trim(),questions:$('#questions-path').value.trim()}};if(db)payload.database_base64=await filesToBase64(db);const info=await api('/api/import',payload);state.project=info.project_id;$('#import-status').textContent=`Imported ${info.database_id}: ${info.history_count} SQL sources, ${info.question_count} questions.`;pendingRun(false);}catch(e){$('#import-status').textContent=e.message;}};$('#build-ontology').onclick=()=>beginRun('build');$('#update-ontology').onclick=()=>beginRun('update');$('#construct-family').onclick=()=>beginRun('construct');$('#run-queries').onclick=()=>beginRun('query');}
function initResizers(){let drag=null;document.querySelectorAll('.resizer').forEach(el=>el.onmousedown=e=>{drag={el,target:$('#'+el.dataset.rz),x:e.clientX,width:$('#'+el.dataset.rz).getBoundingClientRect().width};e.preventDefault();});window.addEventListener('mousemove',e=>{if(drag){const width=Math.max(180,Math.min(620,drag.width+e.clientX-drag.x));drag.target.style.width=width+'px';drag.target.style.flex='0 0 '+width+'px';}});window.addEventListener('mouseup',()=>drag=null);}
document.querySelectorAll('#sr-tabs button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('#api-open').onclick=()=>tab('local');$('#db-search').oninput=drawDatabases;$('#replaySpeed').onchange=()=>{if(state.timer){stop();playNext();}};initAPI();initResizers();json('data/catalog.json').then(c=>{state.catalog=c;drawDatabases();return selectDatabase('formula_1');}).catch(e=>{$('#detail').innerHTML=`<div class="empty">${esc(e.message)}</div>`;});
